|leveling3    = {{st|Total Minimum/Minion Damage|{{ap|80 to 280}}|Minimum/Minion Damage Per Tick|{{ap|80/5 to 280/5}}}}
{{st|Total Monster Damage Cap|{{ap|260 to 500}}|Monster Damage Cap Per Tick|{{ap|260/5 to 500/5}}}}
|range        = {{tt|{{fd|0.75}} seconds{{times}}{{as|35% movement speed}}|Lunge distance, see notes}}
|target range = {{dv|{{tt|500|Flame standard length}}|{{tt|560|Final gout of flame length}}}}
|effect radius= {{tt|175|Flame width}}
